begin;
with j as (select * from jsonb_to_recordset($law7d0024$[{"code_id":"BK_RF","article_number":"23","version_date":"1998-07-31","article_text":"1. Код классификации источников финансирования дефицитов бюджетов состоит из:\n\n1)  кода главного администратора источников финансирования дефицитов бюджетов;\n\n2)  кода группы,  подгруппы,  статьи и вида источника финансирования дефицитов бюджетов;\n\n3)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. (Пункт утратил силу - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n3. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами источников финансирования дефицитов бюджетов являются:\n\n1)  источники внутреннего финансирования дефицитов бюджетов:\n\nгосударственные (муниципальные)  ценные бумаги,  номинальная стоимость которых указана в валюте Российской Федерации;\n\nкредиты кредитных организаций в валюте Российской Федерации;\n\nбюджетные кредиты из других бюджетов бюджетной системы Российской Федерации; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nкредиты международных финансовых организаций в валюте Российской Федерации;\n\nкредиты иностранных банков в валюте Российской Федерации; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nизменение остатков средств на счетах по учету средств бюджета;\n\nиные источники внутреннего финансирования дефицитов бюджетов;\n\n2)  источники внешнего финансирования дефицитов бюджетов:\n\nгосударственные ценные бумаги,  номинальная стоимость которых указана в иностранной валюте;\n\nкредиты иностранных государств,  включая целевые иностранные кредиты,  международных финансовых организаций,  иных субъектов международного права,  иностранных юридических лиц в иностранной валюте; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nкредиты кредитных организаций в иностранной валюте;\n\nбюджетные кредиты в иностранной валюте,  предоставленные Российской Федерацией в рамках использования целевых иностранных кредитов; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nиные источники внешнего финансирования дефицитов бюджетов.\n\n4. Перечень статей источников финансирования дефицитов бюджетов утверждается законом (решением)  о соответствующем бюджете при утверждении источников финансирования дефицита бюджета. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n5. Министерство финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса утверждает: (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\nобщие требования к порядку формирования перечня кодов статей и видов источников финансирования дефицитов бюджетов;\n\nперечень кодов видов источников финансирования дефицитов бюджетов,  главными администраторами которых являются органы государственной власти Российской Федерации,  органы управления государственными внебюджетными фондами Российской Федерации и (или)  находящиеся в их ведении казенные учреждения.\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце третьем настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых источников финансирования дефицит\n\nприкладные научные исследования в области общегосударственных вопросов;\n\nдругие общегосударственные вопросы;\n\n2)  национальная оборона:\n\nВооруженные Силы Российской Федерации;\n\nмодернизация Вооруженных Сил Российской Федерации и воинских формирований;\n\nмобилизационная и вневойсковая подготовка;\n\nмобилизационная подготовка экономики;\n\nподготовка и участие в обеспечении коллективной безопасности и миротворческой деятельности;\n\nядерно-оружейный комплекс;\n\nреализация международных обязательств в сфере военно-технического сотрудничества;\n\nприкладные научные исследования в области национальной обороны;\n\nдругие вопросы в области национальной обороны;\n\n3)  национальная безопасность и правоохранительная деятельность:\n\nорганы прокуратуры и следствия; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nорганы внутренних дел;\n\nвойска национальной гвардии Российской Федерации; (В редакции Федерального закона от 03.07.2016 № 229-ФЗ)\n\nорганы юстиции;\n\nсистема исполнения наказаний;\n\nорганы безопасности;\n\nорганы пограничной службы;\n\nабзац; (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nзащита населения и территории от чрезвычайных ситуаций природного и техногенного характера,  пожарная безопасность; (В редакции Федерального закона от 31.07.2020 № 263-ФЗ)\n\nгражданская оборона; (В редакции Федерального закона от 31.07.2020 № 263-ФЗ)\n\nмиграционная политика;\n\nмодернизация войск национальной гвардии Российской Федерации,  спасательных воинских формирований федерального органа исполнительной власти,  уполномоченного на решение задач в области гражданской обороны,  а также правоохранительных и иных органов; (В редакции федеральных законов от 27.07.2010 № 223-ФЗ; от 03.07.2016 № 229-ФЗ)\n\nприкладные научные исследования в области национальной безопасности и правоохранительной деятельности;\n\nдругие вопросы в области национальной безопасности и правоохранительной деятельности;\n\n4)  национальная экономика:\n\nобщеэкономические вопросы;\n\nтопливно-энергетический комплекс;\n\nисследование и использование космического пространства;\n\nвоспроизводство минерально-сырьевой базы;\n\nсельское хозяйство и рыболовство;\n\nводное хозяйство; (В редакции Федерального закона от 14.07.2008 № 118-ФЗ)\n\nлесное хозяйство;\n\nтранспорт;\n\nдорожное хозяйство (дорожные фонды) ; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nсвязь и информатика;\n\nприкладные научные исследования в области национальной экономики;\n\nдругие вопросы в области национальной экономики;\n\n5)  жилищно-коммунальное хозяйство:\n\nжилищное хозяйство;\n\nкоммунальное хозяйство;\n\nблагоустройство;\n\nприкладные научные исследования в области жилищно-коммунального хозяйства;\n\nдругие вопросы в области жилищно-коммунального хозяйства;\n\n6)  охрана окружающей среды:\n\nэкологический контроль;\n\nсбор,  удаление отходов и очистка сточных вод;\n\nохрана объектов растительного и животного мира и среды их обитания;\n\nприкладные научные исследования в области охраны окружающей среды;\n\nдругие вопросы в области охраны окружающей среды;\n\n7)  образование:\n\nдошкольное образование;\n\nобщее образование;\n\nдополнительное образование детей; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nсреднее профессиональное образование;\n\nпрофессиональная подготовка,  переподготовка и повышение квалификации;\n\nвысшее образование; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nмолодежная политика; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nприкладные научные исследования в области образования;\n\nдругие вопросы в области образования;\n\n8)  культура,  кинематография: (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nкинематография;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nприкладные научные исследования в области культуры,  кинематографии; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nдругие вопросы в области культуры,  кинематографии; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n9)  здравоохранение: (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nстационарная медицинская помощь;\n\nамбулаторная помощь;\n\nмедицинская помощь в дневных стационарах всех типов;\n\nскорая медицинская помощь;\n\nсанаторно-оздоровительная помощь;\n\nзаготовка,  переработка,  хранение и обеспечение безопасности донорской крови и ее компонентов;\n\nсанитарно-эпидемиологическое благополучие;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nприкладные научные исследования в области здравоохранения; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nдругие вопросы в области здравоохранения; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n10)  социальная политика:\n\nпенсионное обеспечение;\n\nсоциальное обслуживание населения;\n\nсоциальное обеспечение населения;\n\nохрана семьи и детства;\n\nприкладные научные исследования в области социальной политики;\n\nдругие вопросы в области социальной политики;\n\n11)  физическая культура и спорт:\n\nфизическая культура;\n\nмассовый спорт;\n\nспорт высших достижений;\n\nприкладные научные исследования в области физической культуры и спорта;\n\nдругие вопросы в области физической культуры и спорта;\n\n(Подпункт в редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n12)  средства массовой информации:\n\nтелевидение и радиовещание;\n\nпериодическая печать и издательства;\n\nприкладные научные исследования в области средств массовой информации;\n\nдругие вопросы в области средств массовой информации;\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n13)  обслуживание государственного (муниципального)  долга: (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nобслуживание государственного (муниципального)  внутреннего долга; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nобслуживание государственного (муниципального)  внешнего долга; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n14)  межбюджетные трансферты общего характера бюджетам бюджетной системы Российской Федерации: (В редакции Федерального закона от 04.10.2014 № 283-ФЗ)\n\nдотации на выравнивание бюджетной обеспеченности субъектов Российской Федерации и муниципальных образований;\n\nиные дотации;\n\nпрочие межбюджетные трансферты общего характера.\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n4. Перечень разделов,  подразделов,  целевых статей (государственных (муниципальных)  программ и непрограммных направлений деятельности) ,  групп (групп и подгрупп)  видов расходов бюджета утверждается в составе ведомственной структуры расходов бюджета законом (решением)  о бюджете либо в установленных настоящим Кодексом случаях сводной бюджетной росписью соответствующего бюджета. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nЦелевые статьи расходов бюджетов формируются в соответствии с государственными (муниципальными)  программами,  не включенными в государственные (муниципальные)  программы направлениями деятельности органов государственной власти (государственных органов) ,  органов управления государственными внебюджетными фондами,  органов местного самоуправления,  органов местной администрации,  наиболее значимых учреждений науки,  образования,  культуры и здравоохранения,  указанных в ведомственной структуре расходов бюджета (в целях настоящего Кодекса - непрограммные направления деятельности) ,  и (или)  расходными обязательствами,  подлежащими исполнению за счет средств соответствующих бюджетов. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nКаждому публичному нормативному обязательству,  межбюджетному трансферту,  инициативному проекту,  предусмотренному статьей 261 Федерального закона от 6 октября 2003 года № 131-ФЗ \"Об общих принципах организации местного самоуправления в Российской Федерации\",  поддержанному органами местного самоуправления (далее - инициативный проект) ,  присваиваются уникальные коды классификации расходов бюджетов. (В редакции федеральных законов от 30.12.2008 № 310-ФЗ,  от 07.05.2013 № 104-ФЗ,  от 26.07.2019 № 199-ФЗ,  от 20.07.2020 № 216-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов устанавливаются с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса финансовым органом,  осуществляющим составление и организацию исполнения бюджета,  если иное не установлено настоящим Кодексом.  (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов,  финансовое обеспечение которых осуществляется за счет межбюджетных субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  определяются в порядке,  установленном финансовым органом,  осуществляющим составление и организацию исполнения бюджета,  из которого предоставляются указанные межбюджетные субсидии,  субвенции и иные межбюджетные трансферты,  имеющие целевое назначение,  с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 09.04.2009 № 58-ФЗ,  от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов государственных внебюджетных фондов Российской Федерации,  территориальных государственных внебюджетных фондов устанавливаются соответственно Министерством финансов Российской Федерации,  финансовым органом субъекта Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n5. Код вида расходов включает группу,  подгруппу и элемент вида расходов. (Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n6. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами видов расходов являются:\n\n1)  группа \"Расходы на выплаты персоналу в целях обеспечения выполнения функций государственными (муниципальными)  органами,  казенными учреждениями,  органами управления государственными внебюджетными фондами\":\n\nподгруппа \"Расходы на выплаты персоналу казенных учреждений\";\n\nподгруппа \"Расходы на выплаты персоналу государственных (муниципальных)  органов\";\n\nподгруппа \"Расходы на выплаты персоналу в сфере национальной безопасности,  правоохранительной деятельности и обороны\";\n\nподгруппа \"Расходы на выплаты персоналу государственных внебюджетных фондов\";\n\n2)  группа \"Закупка товаров,  работ и услуг для обеспечения государственных (муниципальных)  нужд\": (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Разработка,  закупка и ремонт вооружений,  военной и специальной техники,  продукции производственно-технического назначения и имущества\";\n\nподгруппа \"Закупка товаров,  работ и услуг для обеспечения специальным топливом и горюче-смазочными материалами,  продовольственного и вещевого обеспечения органов в сфере национальной безопасности,  правоохранительной деятельности и обороны\";\n\nподгруппа \"Закупка товаров,  работ и услуг в целях формирования государственного материального резерва\";\n\nподгруппа \"Иные закупки товаров,  работ и услуг для обеспечения государственных (муниципальных)  нужд\"; (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\n3)  группа \"Социальное обеспечение и иные выплаты населению\":\n\nподгруппа \"Публичные нормативные социальные выплаты гражданам\";\n\nподгруппа \"Социальные выплаты гражданам,  кроме публичных нормативных социальных выплат\";\n\nподгруппа \"Публичные нормативные выплаты гражданам несоциального характера\";\n\nподгруппа \"Стипендии\";\n\nподгруппа \"Премии и гранты\";\n\nподгруппа \"Иные выплаты населению\";\n\n4)  группа \"Капитальные вложения в объекты государственной (муниципальной)  собственности\": (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Бюджетные инвестиции\";\n\nподгруппа \"Субсидии бюджетным и автономным учреждениям,  государственным (муниципальным)  унитарным предприятиям на осуществление капитальных вложений в объекты капитального строительства государственной (муниципальной)  собственности или приобретение объектов недвижимого имущества в государственную (муниципальную)  собственность\"; (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Бюджетные инвестиции иным юридическим лицам\";\n\n5)  группа \"Межбюджетные трансферты\":\n\nподгруппа \"Дотации\";\n\nподгруппа \"Субсидии\";\n\nподгруппа \"Субвенции\";\n\nподгруппа \"Иные межбюджетные трансферты\";\n\nабзац; (Утратил силу - Федеральный закон от 14.07.2022 № 264-ФЗ)\n\nподгруппа \"Межбюджетные трансферты бюджету Федерального фонда обязательного медицинского страхования\";\n\nподгруппа \"Межбюджетные трансферты бюджету Фонда пенсионного и социального страхования Российской Федерации\"; (В редакции  Федерального закона от 14.07.2022 № 264-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 31.07.2020 № 263-ФЗ)\n\n6)  группа \"Предоставление субсидий бюджетным,  автономным учреждениям и иным некоммерческим организациям\":\n\nподгруппа \"Субсидии бюджетным учреждениям\";\n\nподгруппа \"Субсидии автономным учреждениям\";\n\nподгруппа \"Субсидии некоммерческим организациям (за исключением государственных (муниципальных)  учреждений,  государственных корпораций (компаний) ,  публично-правовых компаний) \"; (В редакции Федерального закона от 26.07.2019 № 199-ФЗ)\n\n7)  группа \"Обслуживание государственного (муниципального)  долга\":\n\nподгруппа \"Обслуживание государственного долга Российской Федерации\";\n\nподгруппа \"Обслуживание государственного долга субъекта Российской Федерации\";\n\nподгруппа \"Обслуживание муниципального долга\";\n\n8)  группа \"Иные бюджетные ассигнования\":\n\nподгруппа \"Субсидии юридическим лицам (кроме некоммерческих организаций) ,  индивидуальным предпринимателям,  физическим лицам - производителям товаров,  работ,  услуг\";\n\nподгруппа \"Субсидии государственным корпорациям (компаниям) ,  публично-правовым компаниям\"; (В редакции Федерального закона от 18.07.2017 № 178-ФЗ)\n\nподгруппа \"Исполнение судебных актов\";\n\nподгруппа \"Исполнение государственных (муниципальных)  гарантий без права регрессного требования гаранта к принципалу или уступки гаранту прав требования бенефициара к принципалу\";\n\nподгруппа \"Уплата налогов,  сборов и иных платежей\";\n\nподгруппа \"Предоставление платежей,  взносов,  безвозмездных перечислений субъектам международного права\";\n\nподгруппа \"Резервные средства\";\n\nподгруппа \"Специальные расходы\";\n\nподгруппа \"Субсидии юридическим лицам,  индивидуальным предпринимателям,  являющимся стороной концессионных соглашений,  соглашений о государственно-частном партнерстве,  муниципально-частном партнерстве,  а также на финансовое обеспечение (возмещение)  затрат,  связанных с финансовой арендой (лизингом) \". (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n7. Перечень единых для бюджетов бюджетной системы Российской Федерации элементов видов расходов классификации расходов бюджетов устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n8. Министерство финансов Российской Федерации утверждает общие требования к порядку формирования перечня кодов элементов видов расходов классификации расходов бюджетов при дополнительной детализации расходов бюджетов субъектов Российской Федерации (местных бюджетов)  с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n9. Внесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзацах четвертом - шестом пункта 4 настоящей статьи,  осуществляется в связи с внесением изменений в сводную бюджетную роспись федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации и применяется к отношениям,  возникшим с момента внесения изменений в сводную бюджетную роспись соответствующего бюджета. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 23. Классификация источников финансирования дефицитов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2891f6070baecb0ec4a18768898c741fe39b5c6316045620521e0f6b514cd9df"},{"code_id":"BK_RF","article_number":"23.1","version_date":"1998-07-31","article_text":"1. Код классификации операций сектора государственного управления включает группу,  статью и подстатью классификации операций сектора государственного управления. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n2. Едиными для бюджетов бюджетной системы Российской Федерации группами классификации операций сектора государственного управления являются:\n\n1)  доходы;\n\n2)  расходы;\n\n3)  поступление нефинансовых активов;\n\n4)  выбытие нефинансовых активов;\n\n5)  поступление финансовых активов;\n\n6)  выбытие финансовых активов;\n\n7)  увеличение обязательств;\n\n8)  уменьшение обязательств.\n\n(Пункт в редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n3. Единый для бюджетов бюджетной системы Российской Федерации перечень статей и подстатей классификации операций сектора государственного управления устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n4. Порядок применения классификации операций сектора государственного управления устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n5. Министерство финансов Российской Федерации утверждает общие требования к порядку формирования перечня подстатей классификации операций сектора государственного управления при дополнительной детализации операций сектора государственного управления с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 23.1. Классификация операций сектора государственного управления","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d80d3e75f0c784ba964477ef632b25515267d8efc54419812192dd02111bbd37"},{"code_id":"BK_RF","article_number":"24","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 24.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"25","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 25.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"26","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 26.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"27","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 27.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"28","version_date":"1998-07-31","article_text":"Бюджетная система Российской Федерации основана на принципах:\n\nединства бюджетной системы Российской Федерации;\n\nразграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nсамостоятельности бюджетов;\n\nравенства бюджетных прав субъектов Российской Федерации,  муниципальных образований; (Дополнение абзацем - Федеральный закон от 20.08.2004 № 120-ФЗ)\n\nполноты отражения доходов,  расходов и источников финансирования дефицитов бюджетов; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nсбалансированности бюджета;\n\nэффективности использования бюджетных средств; (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)\n\nобщего (совокупного)  покрытия расходов бюджетов;\n\nпрозрачности (открытости) ; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nучастия граждан в бюджетном процессе; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nдостоверности бюджета;\n\nадресности и целевого характера бюджетных средств;\n\nподведомственности расходов бюджетов; (Дополнение абзацем - Федеральный закон от 26.04.2007 № 63-ФЗ)\n\nединства кассы. (Дополнение абзацем - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 28. Перечень принципов бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1576b05a5d73b00a6cfb31520b9d27483b5f7ae80026a88ae712246d1c695e7"},{"code_id":"BK_RF","article_number":"29","version_date":"1998-07-31","article_text":"Принцип единства бюджетной системы Российской Федерации означает единство бюджетного законодательства Российской Федерации,  принципов организации и функционирования бюджетной системы Российской Федерации,  форм бюджетной документации и бюджетной отчетности,  бюджетной классификации Российской Федерации,  бюджетных мер принуждения за нарушение бюджетного законодательства Российской Федерации,  единый порядок установления и исполнения расходных обязательств,  формирования доходов и осуществления расходов бюджетов бюджетной системы Российской Федерации,  ведения бюджетного учета и составления бюджетной отчетности бюджетов бюджетной системы Российской Федерации и казенных учреждений,  единство порядка исполнения судебных актов по обращению взыскания на средства бюджетов бюджетной системы Российской Федерации. (В редакции  федеральных законов от 27.12.2005 № 197-ФЗ,  от 26.04.2007 № 63-ФЗ,  от 08.05.2010 № 83-ФЗ,  от 23.07.2013 № 252-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 29. Принцип единства бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2424db99b59ebe914b7230fab81f7f92abf0f0a294864e7544d058958194f09"},{"code_id":"BK_RF","article_number":"3","version_date":"1998-07-31","article_text":"1. Президент Российской Федерации издает указы,  регулирующие бюджетные правоотношения,  указанные в пункте 1 статьи 1 настоящего Кодекса. Указы Президента Российской Федерации не могут противоречить настоящему Кодексу и федеральным законам,  указанным в статье 2 настоящего Кодекса.\n\n2. На основании и во исполнение настоящего Кодекса,  федеральных законов,  указанных в статье 2 настоящего Кодекса,  указов Президента Российской Федерации,  предусмотренных пунктом 1 настоящей статьи,  Правительство Российской Федерации принимает нормативные правовые акты,  регулирующие бюджетные правоотношения,  предусмотренные статьей 1 настоящего Кодекса.\n\n21. Совет Федерации Федерального Собрания Российской Федерации,  Государственная Дума Федерального Собрания Российской Федерации принимают акты,  регулирующие бюджетные правоотношения,  в случаях,  предусмотренных настоящим Кодексом. (Дополнение пунктом - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\n3. Федеральные органы исполнительной власти принимают акты,  регулирующие бюджетные правоотношения,  предусмотренные статьей 1 настоящего Кодекса,  в случаях и пределах,  которые предусмотрены настоящим Кодексом,  федеральными законами,  указанными в статье 2 настоящего Кодекса,  и актами,  указанными в пунктах 1 и 2 настоящей статьи.\n\n4. Органы государственной власти субъектов Российской Федерации принимают нормативные правовые акты,  регулирующие бюджетные правоотношения,  в пределах своей компетенции в соответствии с настоящим Кодексом.\n\n5. Органы местного самоуправления принимают муниципальные правовые акты,  регулирующие бюджетные правоотношения,  в пределах своей компетенции в соответствии с настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 3. Нормативные правовые акты,  регулирующие бюджетные правоотношения","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ff108cd5f3cc567b4eda41fe9e2e24bca90d8efd4983b08ea5af4456863169e"},{"code_id":"BK_RF","article_number":"30","version_date":"1998-07-31","article_text":"Принцип разграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации означает закрепление в соответствии с законодательством Российской Федерации доходов,  расходов и источников финансирования дефицитов бюджетов за бюджетами бюджетной системы Российской Федерации,  а также определение полномочий органов государственной власти (органов местного самоуправления)  и органов управления государственными внебюджетными фондами по формированию доходов бюджетов,  источников финансирования дефицитов бюджетов и установлению и исполнению расходных обязательств публично-правовых образований.\n\nОрганы государственной власти (органы местного самоуправления)  и органы управления государственными внебюджетными фондами не вправе налагать на юридические и физические лица не предусмотренные законодательством Российской Федерации финансовые и иные обязательства по обеспечению выполнения своих полномочий.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 30. Принцип разграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"773b42ae70b5fd45755d6690b0630b8d599d96131e8e24b03ef1598a957574a1"}]$law7d0024$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
